    \item Give the result in the simplest form.
    \item State explicitly the expression to be evaluated.
    \item Evaluate the determinant.
\end{itemize}
\end{center}
Let $D$ be the determinant of the given matrix:
\[ D = \begin{vmatrix} \sec^2 x & 1 & 1 \\ \cos^2 x & \cos^2 x & \csc^2 x \\ 1 & \cos^2 x & \cot^2 x \end{vmatrix} \]
Expanding the determinant along the first row, we have
\begin{align*} D &= \sec^2 x \begin{vmatrix} \cos^2 x & \csc^2 x \\ \cos^2 x & \cot^2 x \end{vmatrix} - 1 \begin{vmatrix} \cos^2 x & \csc^2 x \\ 1 & \cot^2 x \end{vmatrix} + 1 \begin{vmatrix} \cos^2 x & \cos^2 x \\ 1 & \cos^2 x \end{vmatrix} \\ &= \sec^2 x \left( \cos^2 x \cot^2 x - \csc^2 x \cos^2 x \right) - \left( \cos^2 x \cot^2 x - \csc^2 x \right) + \left( \cos^4 x - \cos^2 x \right) \\ &= \sec^2 x \left( \cos^2 x \frac{\cos^2 x}{\sin^2 x} - \csc^2 x \cos^2 x \right) - \left( \cos^2 x \frac{\cos^2 x}{\sin^2 x} - \csc^2 x \right) + \cos^2 x ( \cos^2 x - 1) \\ &= \sec^2 x \left( \frac{\cos^4 x}{\sin^2 x} - \frac{\cos^2 x \csc^2 x}{\sin^2 x} \right) - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\sec^2 x}{\sin^2 x} \cos^4 x - \frac{\sec^2 x}{\sin^2 x} \cos^2 x \csc^2 x - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\frac{1}{\cos^2 x}}{\sin^2 x} \cos^4 x - \frac{\frac{1}{\cos^2 x}}{\sin^2 x} \cos^2 x \frac{1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x}{\sin^2 x} - \frac{\cos^2 x}{\sin^4 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x}{\sin^2 x} - \frac{\cos^2 x}{\sin^4 x} - \frac{\cos^4 x}{\sin^2 x} + \csc^2 x + \cos^4 x - \cos^2 x\end{align*} 
Let $x = \frac{\pi}{4}$. Then $\cos x = \frac{1}{\sqrt{2}}$ and $\sin x = \frac{1}{\sqrt{2}}$.
\[ D = \begin{vmatrix} \sec^2 \frac{\pi}{4} & 1 & 1 \\ \cos^2 \frac{\pi}{4} & \cos^2 \frac{\pi}{4} & \csc^2 \frac{\pi}{4} \\ 1 & \cos^2 \frac{\pi}{4} & \cot^2 \frac{\pi}{4} \end{vmatrix} = \begin{vmatrix} 2 & 1 & 1 \\ \frac{1}{2} & \frac{1}{2} & 2 \\ 1 & \frac{1}{2} & 1 \end{vmatrix} \]
$D = 2( \frac{1}{2} \cdot 1 - 2 \cdot \frac{1}{2}) - 1( \frac{1}{2} \cdot 1 - 2 \cdot 1) + 1( \frac{1}{2} \cdot \frac{1}{2} - \frac{1}{2} \cdot 1) $
$D = 2( \frac{1}{2} - 1) - 1( \frac{1}{2} - 2) + 1( \frac{1}{4} - \frac{1}{2}) $
$D = 2(-\frac{1}{2}) - 1(-\frac{3}{2}) + 1(-\frac{1}{4}) $
$D = -1 + \frac{3}{2} - \frac{1}{4} = \frac{-4+6-1}{4} = \frac{1}{4}$

Another method is to notice that the second row is $\cos^2 x, \cos^2 x, \csc^2 x$.
The third row is $1, \cos^2 x, \cot^2 x$. 
If $x = \frac{\pi}{4}$, then $\cos x = \frac{1}{\sqrt{2}}$, $\sin x = \frac{1}{\sqrt{2}}$, so $\cos^2 x = \frac{1}{2}$, $\csc^2 x = 2$, $\cot^2 x = 1$.
\begin{align*} \begin{vmatrix} \sec^2 \frac{\pi}{4} & 1 & 1 \\ \cos^2 \frac{\pi}{4} & \cos^2 \frac{\pi}{4} & \csc^2 \frac{\pi}{4} \\ 1 & \cos^2 \frac{\pi}{4} & \cot^2 \frac{\pi}{4} \end{vmatrix} &= \begin{vmatrix} 2 & 1 & 1 \\ \frac{1}{2} & \frac{1}{2} & 2 \\ 1 & \frac{1}{2} & 1 \end{vmatrix} \\ &= 2 \begin{vmatrix} \frac{1}{2} & 2 \\ \frac{1}{2} & 1 \end{vmatrix} - 1 \begin{vmatrix} \frac{1}{2} & 2 \\ 1 & 1 \end{vmatrix} + 1 \begin{vmatrix} \frac{1}{2} & \frac{1}{2} \\ 1 & \frac{1}{2} \end{vmatrix} \\ &= 2 \left( \frac{1}{2} - 1 \right) - 1 \left( \frac{1}{2} - 2 \right) + 1 \left( \frac{1}{4} - \frac{1}{2} \right) \\ &= 2 \left( -\frac{1}{2} \right) - 1 \left( -\frac{3}{2} \right) + 1 \left( -\frac{1}{4} \right) \\ &= -1 + \frac{3}{2} - \frac{1}{4} = \frac{-4 + 6 - 1}{4} = \frac{1}{4} \end{align*} 
So $D = \frac{1}{4}$.

\boxed{\frac{1}{4}}

